'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const templates=[
{id:'everyday',name:'The Everyday',description:'Clean lines. Clear intentions.',category:'Minimal',layout:'minimal',color:'#294c40',bg:'#e3ebdf',badge:'THE ALL-ROUNDER'},
{id:'editorial',name:'The Editorial',description:'A little personality. Lots of polish.',category:'Creative',layout:'editorial',color:'#58493d',bg:'#eee8e0',badge:''},
{id:'momentum',name:'The Momentum',description:'Make your next move count.',category:'Professional',layout:'bold',color:'#365cc5',bg:'#e4eafa',badge:'BOLD & BALANCED'},
{id:'first',name:'The First Chapter',description:'Big ambitions start here.',category:'Student',layout:'student',color:'#4e6040',bg:'#e7eccf',badge:'FIRST JOB ENERGY'},
{id:'studio',name:'The Studio',description:'For the creatively inclined.',category:'Creative',layout:'creative',color:'#a95039',bg:'#f3dfd6',badge:''},
{id:'signal',name:'The Signal',description:'Let your skills do the talking.',category:'Tech',layout:'tech',color:'#4755a1',bg:'#e6e4f3',badge:''},
{id:'classic',name:'The Classic',description:'Timeless for a reason.',category:'Professional',layout:'classic',color:'#353b38',bg:'#e3e7e9',badge:''},
{id:'scholar',name:'The Scholar',description:'A home for your hard work.',category:'Academic',layout:'academic',color:'#4a5850',bg:'#e9e9dc',badge:'CV READY'}];
let currentCategory='All templates',currentView='templates';
const sample={name:'Alex Morgan',role:'Product Designer',email:'alex.morgan@example.com',phone:'+1 555 012 3456',location:'Brooklyn, New York',website:'alexmorgan.design',summary:'Thoughtful product designer turning complex problems into simple, human experiences. Curious by nature. Collaborative by default.',experience:[{title:'Product Designer',company:'Studio North',dates:'2023 – Present',details:'Designed an onboarding experience that increased completion by 28%.\nPartnered with engineers to ship a design system used across 4 products.'},{title:'Design Intern',company:'Sunday Studio',dates:'2022 – 2023',details:'Translated user interviews into clear, accessible digital experiences.\nBuilt and tested prototypes with a cross-functional team.'}],education:[{degree:'BFA, Communication Design',school:'Brooklyn School of Design',dates:'2018 – 2022',details:'Graduated with honors. Design society member.'}],skills:'Product design, Figma, Prototyping, User research, Design systems, Accessibility',projects:[{title:'Neighborhood Notes',link:'Community design project',details:'Designed a local guide connecting residents with independent businesses.'}],extraTitle:'Certifications & achievements',extra:''};
const empty=()=>({name:'',role:'',email:'',phone:'',location:'',website:'',summary:'',experience:[],education:[],skills:'',projects:[],extraTitle:'Certifications & achievements',extra:''});
let state={template:'everyday',color:'#294c40',data:empty(),step:0};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function mini(t){return `<div aria-hidden="true" class="mini-paper layout-${t.layout}" style="--resume-accent:${t.color}"><div class="mini-name">ALEX MORGAN</div><div class="mini-role">PRODUCT DESIGNER</div><div class="mini-contact">Brooklyn, NY · alex.morgan@example.com · alexmorgan.design</div><div class="mini-section"><h4>Profile</h4><p>Thoughtful designer turning complex problems into simple, human experiences. Curious by nature. Collaborative by default.</p></div><div class="mini-section"><h4>Experience</h4><b>Product Designer · Studio North</b><p>2023 – Present</p><ul><li>Designed an onboarding experience that increased completion by 28%.</li><li>Partnered with engineers to ship a thoughtful design system.</li></ul><b>Design Intern · Sunday Studio</b><p>2022 – 2023</p><ul><li>Translated research into accessible digital experiences.</li><li>Created clear, human-centered prototypes.</li></ul></div><div class="mini-section"><h4>Education</h4><b>Brooklyn School of Design</b><p>BFA, Communication Design · 2018 – 2022</p></div><div class="mini-section"><h4>Skills</h4><p>Product design · Figma · User research · Prototyping<br>Design systems · Accessibility · Collaboration</p></div><div class="mini-section"><h4>Selected projects</h4><b>Neighborhood Notes</b><p>A local guide connecting residents with independent businesses.</p></div></div>`}
function renderGallery(){ $('#categories').innerHTML=['All templates','Minimal','Professional','Creative','Student','Tech','Academic'].map(c=>`<button class="chip ${c===currentCategory?'active':''}" data-category="${c}" aria-pressed="${c===currentCategory}">${c}</button>`).join('');const list=templates.filter(t=>currentCategory==='All templates'||t.category===currentCategory);$('#result-count').textContent=`${list.length} template${list.length===1?'':'s'}`;$('#template-grid').innerHTML=list.map(t=>`<article class="template-card"><button class="card-cover" data-template="${t.id}" style="--card-bg:${t.bg}" aria-label="Use ${t.name} template">${t.badge?`<span class="template-badge">${t.badge}</span>`:''}${mini(t)}</button><div class="card-meta"><div><h3>${t.name}</h3><p>${t.description}</p></div><button class="card-use" data-template="${t.id}" aria-label="Use ${t.name}">+</button></div></article>`).join('')}
function showView(view){currentView=view;$$('.page-view').forEach(el=>el.classList.toggle('hidden',el.id!==`${view}-view`));$$('.nav-link').forEach(el=>el.classList.toggle('active',el.dataset.view===view));if(view==='editor'&&typeof renderEditor==='function')renderEditor();if(view==='tips'&&typeof renderTips==='function')renderTips();$('#site-footer').classList.toggle('hidden',view==='editor');history.replaceState(null,'','#'+view);window.scrollTo(0,0)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.category){currentCategory=b.dataset.category;renderGallery()}if(b.dataset.template){const t=templates.find(t=>t.id===b.dataset.template);state.template=t.id;state.color=t.color;showView('editor')}if(b.dataset.view)showView(b.dataset.view);if(b.dataset.action==='create')showView('editor');if(b.hasAttribute('data-close'))b.closest('dialog').close()});
renderGallery();
const steps=['The basics','Your summary','Experience','Education','Skills','Projects','Extra details'];
const stepDescriptions=['Let’s start with a proper introduction.','A short introduction with a clear point of view.','Your work, and the difference you made.','There’s more than one way to learn.','The things you bring to the table.','Side projects count. So does curiosity.','A little more of what makes you, you.'];
const stepHints=['Use an email you check regularly. City and country are enough—no full street address needed.','Aim for 2–3 specific sentences. Mention your focus, a strength, and what you want to do next.','Lead with an action. Add what you did and a real result. Internships, freelance work, and volunteering count too.','Add your qualification, institution, and dates. New graduate? Relevant coursework can help tell your story.','Separate skills with commas. Include skills you can demonstrate and tools relevant to the role.','Describe the problem, your contribution, and the outcome. A class project or personal build is a great starting point.','Use this space for certifications, awards, languages, publications, or research. Rename the section to suit your CV.'];
let saveOk=true,toastTimer;
try{const saved=JSON.parse(localStorage.getItem('folio-draft-v1'));if(saved&&templates.some(t=>t.id===saved.template)&&saved.data){state={template:saved.template,color:/^#[0-9a-f]{6}$/i.test(saved.color)?saved.color:'#294c40',step:Math.min(6,Math.max(0,Math.trunc(Number(saved.step)||0))),data:empty()};for(const key of ['name','role','email','phone','location','website','summary','skills','extraTitle','extra'])if(typeof saved.data[key]==='string')state.data[key]=saved.data[key].slice(0,20000);for(const key of ['experience','education','projects'])if(Array.isArray(saved.data[key]))state.data[key]=saved.data[key].slice(0,50).filter(x=>x&&typeof x==='object').map(x=>Object.fromEntries(Object.entries(x).filter(([k,v])=>['title','company','dates','details','degree','school','link'].includes(k)&&typeof v==='string').map(([k,v])=>[k,v.slice(0,20000)])));}}catch(e){saveOk=false}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function save(){try{localStorage.setItem('folio-draft-v1',JSON.stringify(state));saveOk=true}catch(e){saveOk=false}const el=$('#save-status');if(el)el.textContent=saveOk?'Saved in this browser':'Saving unavailable · export before leaving'}
function hasContent(){return Object.entries(state.data).some(([k,v])=>k!=='extraTitle'&&(Array.isArray(v)?v.some(r=>Object.values(r).some(x=>String(x).trim())):v.trim()))}
function field(key,label,placeholder='',type='text',wide=false){return `<div class="field ${wide?'wide':''}"><label for="field-${key}">${label}</label><input id="field-${key}" data-field="${key}" type="${type}" value="${esc(state.data[key])}" placeholder="${esc(placeholder)}" ${key==='name'?'autocomplete="name"':key==='email'?'autocomplete="email"':key==='phone'?'autocomplete="tel"':''}></div>`}
function area(key,label,placeholder,rows=6){return `<div class="field wide"><label for="field-${key}">${label}</label><textarea id="field-${key}" data-field="${key}" rows="${rows}" placeholder="${esc(placeholder)}">${esc(state.data[key])}</textarea></div>`}
function entryField(kind,index,key,label,placeholder,textarea=false){const id=`${kind}-${index}-${key}`,value=state.data[kind][index][key]||'';return `<div class="field ${textarea?'wide':''}"><label for="${id}">${label}</label>${textarea?`<textarea id="${id}" data-entry="${kind}" data-index="${index}" data-key="${key}" rows="5" placeholder="${esc(placeholder)}">${esc(value)}</textarea>`:`<input id="${id}" data-entry="${kind}" data-index="${index}" data-key="${key}" value="${esc(value)}" placeholder="${esc(placeholder)}">`}</div>`}
function entryForm(kind){const entries=state.data[kind],singular={experience:'experience',education:'education',projects:'project'}[kind];let html='';if(!entries.length)html=`<div class="empty-entry"><span aria-hidden="true">+</span><h3>Your ${singular} belongs here.</h3><p>${kind==='experience'?'Paid work, volunteering, and internships all count.':kind==='education'?'Add a degree, a course, or professional training.':'Share something you helped bring to life.'}</p></div>`;html+=entries.map((entry,i)=>`<div class="entry-card"><div class="entry-heading"><strong>${kind==='experience'?'Experience':kind==='education'?'Education':'Project'} ${i+1}</strong><div><button type="button" class="entry-small" data-move="${kind}" data-index="${i}" ${i===0?'disabled':''} aria-label="Move ${singular} ${i+1} earlier">Move up</button><button type="button" class="entry-small remove" data-remove="${kind}" data-index="${i}" aria-label="Remove ${singular} ${i+1}">Remove</button></div></div><div class="form-grid">${kind==='experience'?entryField(kind,i,'title','Job title','Product designer')+entryField(kind,i,'company','Organization','Studio North')+entryField(kind,i,'dates','Dates','Jan 2024 – Present')+entryField(kind,i,'details','Achievements · one per line','Designed a new onboarding flow that increased completion by 28%.',true):kind==='education'?entryField(kind,i,'degree','Qualification','BFA, Communication Design')+entryField(kind,i,'school','Institution','Your university or institution')+entryField(kind,i,'dates','Dates','2020 – 2024')+entryField(kind,i,'details','Details · optional','Relevant coursework, honors, or activities',true):entryField(kind,i,'title','Project name','Neighborhood Notes')+entryField(kind,i,'link','Link or context','yourportfolio.com/project')+entryField(kind,i,'details','Your contribution · one per line','What did you make, and what changed because of it?',true)}</div></div>`).join('');return html+`<button type="button" class="button outline add-entry" data-add="${kind}">+ Add ${singular}</button>`}
function stepForm(){switch(state.step){case 0:return `<div class="form-grid">${field('name','Full name *','Alex Morgan')}${field('role','Professional title','Product Designer')}${field('email','Email','alex@example.com','email')}${field('phone','Phone · optional','+1 555 012 3456','tel')}${field('location','Location','City, Country')}${field('website','Portfolio or LinkedIn','yourportfolio.com')}</div>`;case 1:return area('summary','Professional summary','Your focus, strengths, and what you bring to your next role.',7)+`<div class="example-box"><span>AN EXAMPLE, FOR INSPIRATION</span><p>“Curious marketing graduate with experience growing a campus community to 500 members. Skilled in content strategy and analytics, with a focus on making useful ideas easy to discover.”</p></div>`;case 2:return entryForm('experience');case 3:return entryForm('education');case 4:return area('skills','Skills · separated by commas','Figma, User research, Prototyping, Design systems',6)+`<div class="example-box"><span>MAKE IT SPECIFIC</span><p>“Excel, SQL, and data visualization” tells a clearer story than “good with computers.” Keep it honest and relevant.</p></div>`;case 5:return entryForm('projects');case 6:return field('extraTitle','Section heading','Certifications & achievements')+area('extra','Details · one item per line','Certification, issuer, and date\nPublication title, journal, and year\nLanguage and proficiency',8)}}
function renderEditor(){const mobilePreview=$('#editor-view').classList.contains('mobile-preview');const t=templates.find(t=>t.id===state.template);$('#editor-view').innerHTML=`<div class="editor-top"><div><div class="eyebrow">YOUR STORY, TAKING SHAPE</div><h1 id="editor-title">Make it yours.</h1></div><div class="editor-top-actions"><span id="save-status" class="save-status">${saveOk?'Saved in this browser':'Saving unavailable · export before leaving'}</span><button class="button outline share-top-button" data-share>Share</button><button class="button dark" data-export>Export PDF <span aria-hidden="true">↓</span></button></div></div><div class="mobile-switch" aria-label="Editor view"><button class="${mobilePreview?'':'active'}" data-mobile="edit" aria-pressed="${!mobilePreview}">Edit details</button><button class="${mobilePreview?'active':''}" data-mobile="preview" aria-pressed="${mobilePreview}">Live preview</button></div><div class="editor-layout"><aside class="step-sidebar"><span class="sidebar-label">YOUR CONTENT</span><nav aria-label="Resume sections">${steps.map((s,i)=>`<button class="step-button ${i===state.step?'active':''}" data-step="${i}" ${i===state.step?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')}</span>${s}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="text-button" data-view="templates">Change template</button><button class="text-button muted" data-clear>Clear draft</button><span>Only saved on this browser.<br>Export before switching devices.</span></div></aside><div class="form-panel"><div class="step-kicker">SECTION ${state.step+1} OF ${steps.length}</div><h2>${steps[state.step]}</h2><p class="form-intro">${stepDescriptions[state.step]}</p><form id="resume-form" novalidate>${stepForm()}</form><div class="writing-hint"><span aria-hidden="true">✳</span><p>${stepHints[state.step]}</p></div><div class="form-footer"><button class="button outline" data-prev ${state.step===0?'disabled':''}>Back</button><button class="button dark" ${state.step===6?'data-review':'data-next'}>${state.step===6?'Review & export':'Continue'}</button></div><div class="mobile-draft-actions"><button class="text-button muted" data-clear>Clear draft</button><span>Saved only in this browser.</span></div></div><aside class="preview-panel"><div class="preview-toolbar"><label for="template-select" class="sr-only">Resume template</label><select id="template-select">${templates.map(v=>`<option value="${v.id}" ${v.id===t.id?'selected':''}>${v.name}</option>`).join('')}</select><div class="color-choices" aria-label="Resume accent color">${[['#294c40','Forest'],['#365cc5','Cobalt'],['#a95039','Terracotta'],['#4755a1','Indigo'],['#353b38','Charcoal']].map(([c,label])=>`<button class="swatch ${state.color===c?'selected':''}" style="--swatch:${c}" data-color="${c}" aria-label="${label} accent" aria-pressed="${state.color===c}"></button>`).join('')}</div></div><div id="preview-caption" class="preview-caption"></div><div class="paper-scroll"><div id="resume-preview"></div></div><div class="preview-footnote">Selectable text · Clean, single-column layouts</div><div id="resume-checks" class="resume-checks"></div></aside></div>`;renderPreview();save()}
function bullets(value){const lines=value.split('\n').map(s=>s.replace(/^\s*[•\-]\s*/, '').trim()).filter(Boolean);return lines.length?`<ul>${lines.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`:''}
function section(title,body){return body?`<section class="resume-section"><h2>${esc(title)}</h2>${body}</section>`:''}
function filledEntry(e){return Object.values(e).some(v=>String(v).trim())}
function resumeMarkup(d,templateId=state.template,color=state.color){const t=templates.find(t=>t.id===templateId);const exp=section('Experience',d.experience.filter(filledEntry).map(e=>`<div class="resume-entry"><div class="resume-entry-head"><h3>${esc([e.title,e.company].filter(Boolean).join(' · '))}</h3><span>${esc(e.dates)}</span></div>${bullets(e.details||'')}</div>`).join(''));const education=section('Education',d.education.filter(filledEntry).map(e=>`<div class="resume-entry"><div class="resume-entry-head"><h3>${esc(e.degree)}</h3><span>${esc(e.dates)}</span></div>${e.school?`<p class="institution">${esc(e.school)}</p>`:''}${e.details?`<p class="preserve">${esc(e.details)}</p>`:''}</div>`).join(''));const projects=section('Projects',d.projects.filter(filledEntry).map(e=>`<div class="resume-entry"><h3>${esc(e.title)}</h3>${e.link?`<p class="project-link">${esc(e.link)}</p>`:''}${bullets(e.details||'')}</div>`).join(''));return `<article class="resume-paper resume-${t.layout}" style="--resume-accent:${color}"><header class="resume-header"><h1>${esc(d.name||'Your name')}</h1>${d.role?`<p class="resume-role">${esc(d.role)}</p>`:''}<div class="resume-contact">${[d.email,d.phone,d.location,d.website].filter(Boolean).map(s=>`<span>${esc(s)}</span>`).join('<span aria-hidden="true"> · </span>')}</div></header>${section('Profile',d.summary?`<p class="preserve">${esc(d.summary)}</p>`:'')}${t.category==='Student'||t.category==='Academic'?education+exp:exp+education}${section('Skills',d.skills?`<p>${esc(d.skills.split(',').map(s=>s.trim()).filter(Boolean).join(' · '))}</p>`:'')}${projects}${section(d.extraTitle||'Additional information',d.extra?`<p class="preserve">${esc(d.extra)}</p>`:'')}</article>`}
function checkData(){const d=state.data;return [['Add your name',Boolean(d.name.trim())],['Include a way to contact you',Boolean(d.email.trim()||d.phone.trim())],['Show experience, education, or a project',d.experience.some(filledEntry)||d.education.some(filledEntry)||d.projects.some(filledEntry)],['Add relevant skills',Boolean(d.skills.trim())]]}
function renderPreview(){if(!$('#resume-preview'))return;const content=hasContent();$('#resume-preview').innerHTML=resumeMarkup(content?state.data:sample);$('#preview-caption').textContent=content?'LIVE PREVIEW · YOUR RESUME':'EXAMPLE PREVIEW · ADD YOUR DETAILS TO BEGIN';$('#resume-checks').innerHTML=`<div class="check-title"><strong>A quick check before you go</strong><span>${checkData().filter(x=>x[1]).length}/4</span></div>${checkData().map(([label,done])=>`<div class="check-row ${done?'done':''}"><span aria-hidden="true">${done?'✓':'○'}</span>${label}</div>`).join('')}<p>A content checklist, not an ATS score. Always review your PDF before sending.</p>`}
function goStep(value){$('#editor-view').classList.remove('mobile-preview');state.step=Math.max(0,Math.min(6,value));renderEditor();$('.form-panel')?.scrollIntoView({block:'start',behavior:'smooth'});$('#resume-form input, #resume-form textarea, #resume-form button')?.focus({preventScroll:true})}
function requestExport(){if(!state.data.name.trim()){notify('Add your name before exporting.');if(currentView!=='editor')showView('editor');goStep(0);$('#field-name')?.focus();return}if(state.data.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(state.data.email)){notify('Please check your email address before exporting.');goStep(0);$('#field-email')?.focus();return}$('#export-dialog').showModal()}
function resumeMessage(d=state.data){
 const parts=[d.name.trim(),d.role.trim(),[d.email,d.phone,d.location,d.website].filter(v=>v.trim()).join(' | ')].filter(Boolean);
 if(d.summary.trim())parts.push('PROFILE\n'+d.summary.trim());
 const entries=[['EXPERIENCE','experience',['title','company','dates','details']],['EDUCATION','education',['degree','school','dates','details']],['PROJECTS','projects',['title','link','details']]];
 if(['first','scholar'].includes(state.template))[entries[0],entries[1]]=[entries[1],entries[0]];
 for(const [heading,key,fields] of entries)if(d[key].some(filledEntry))parts.push(heading+'\n'+d[key].filter(filledEntry).map(r=>fields.map(f=>r[f]?.trim()).filter(Boolean).join('\n')).join('\n\n'));
 if(d.skills.trim())parts.push('SKILLS\n'+d.skills.trim());
 if(d.extra.trim())parts.push((d.extraTitle.trim()||'Additional information').toUpperCase()+'\n'+d.extra.trim());
 return parts.join('\n\n');
}
function messageLinks(text,title){return {whatsapp:'https://wa.me/?text='+encodeURIComponent(text),email:'mailto:?subject='+encodeURIComponent(title)+'&body='+encodeURIComponent(text)}}
function sharingStatus(message){$('#share-status').textContent=message}
function requestShare(){
 if(!state.data.name.trim()){notify('Add your name before sharing.');if(currentView!=='editor')showView('editor');goStep(0);$('#field-name')?.focus();return}
 const text=resumeMessage(),title=state.data.name.trim()+' — Resume',links=messageLinks(text,title);
 $('#share-content').value=text;
 for(const [id,key,limit] of [['share-whatsapp','whatsapp',8000],['share-email','email',2000]]){
  const link=$('#'+id),long=links[key].length>limit;link.dataset.needsPaste=String(long);
  link.href=long?(key==='whatsapp'?'https://wa.me/?text=':'mailto:?subject='+encodeURIComponent(title)):links[key];
  link.querySelector('small').textContent=long?'Copy text, then paste':key==='whatsapp'?'Choose a contact':'Open a new message';
 }
 $('#share-more').hidden=typeof navigator.share!=='function';
 sharingStatus(links.email.length>2000?'For longer resumes, copy the text and paste it into your email.':typeof navigator.share==='function'?'Your contact details are included. Review the message below.':'Your contact details are included. Use Copy resume text for other apps.');
 $('#share-pdf-file').value='';$('#share-pdf-button').disabled=true;
 $('#share-pdf-status').textContent=typeof navigator.share==='function'&&typeof navigator.canShare==='function'?'Choose a PDF, then select an app from your device’s share menu.':'This browser cannot share PDF files directly. Attach your exported PDF in WhatsApp or your email app.';
 if($('#export-dialog').open)$('#export-dialog').close();
 $('#share-dialog').showModal();
}
async function copyResumeMessage(){
 const text=$('#share-content').value;
 try{if(!navigator.clipboard?.writeText)throw new Error('Clipboard unavailable');await navigator.clipboard.writeText(text);sharingStatus('Resume copied. Paste it into your message, then choose a recipient.');return true}
 catch(e){$('.share-preview').open=true;$('#share-content').focus();$('#share-content').select();sharingStatus('Select and copy the text below, then paste it into your app.');return false}
}
async function shareToMoreApps(){
 if(typeof navigator.share!=='function'){sharingStatus('Use Copy resume text, then paste it into your preferred app.');return}
 try{await navigator.share({title:state.data.name.trim()+' — Resume',text:$('#share-content').value});sharingStatus('Share menu closed. Check the selected app to confirm delivery.')}
 catch(e){sharingStatus(e.name==='AbortError'?'Sharing canceled. Your resume is unchanged.':'Sharing is unavailable here. Copy your resume text or choose WhatsApp or Email.')}
}
function selectedSharePdf(){return $('#share-pdf-file').files?.[0]}
function validSharePdf(file){return Boolean(file&&/\.pdf$/i.test(file.name)&&(!file.type||file.type==='application/pdf')&&file.size>0)}
function pdfSharingSupported(file){try{return typeof navigator.share==='function'&&typeof navigator.canShare==='function'&&navigator.canShare({files:[file]})}catch(e){return false}}
function updatePdfSharing(){const file=selectedSharePdf();const valid=validSharePdf(file),supported=valid&&pdfSharingSupported(file);$('#share-pdf-button').disabled=!supported;$('#share-pdf-status').textContent=!file?'Choose an exported PDF to continue.':!valid?'Choose a non-empty PDF file.':!supported?'This browser cannot share this PDF directly. Attach it in WhatsApp or your email app.':file.name+' is ready. Choose the recipient in your app.'}
async function sharePdf(){const file=selectedSharePdf();if(!validSharePdf(file)||!pdfSharingSupported(file)){updatePdfSharing();return}try{await navigator.share({files:[file],title:state.data.name.trim()+' — Resume'});$('#share-pdf-status').textContent='Share menu closed. Check the selected app to confirm delivery.'}catch(e){$('#share-pdf-status').textContent=e.name==='AbortError'?'Sharing canceled. Your PDF is unchanged.':'Could not open sharing. Attach the PDF directly in your preferred app.'}}

function preparePrint(){if(!state.data.name.trim())return false;$('#print-root').innerHTML=resumeMarkup(state.data);return true}
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.field){state.data[el.dataset.field]=el.value;save();renderPreview()}if(el.dataset.entry){state.data[el.dataset.entry][Number(el.dataset.index)][el.dataset.key]=el.value;save();renderPreview()}});
document.addEventListener('change',e=>{if(e.target.id==='template-select'){const t=templates.find(t=>t.id===e.target.value);state.template=t.id;state.color=t.color;renderEditor();notify(`${t.name} applied. Your content stays with you.`)}});
document.addEventListener('submit',e=>{if(e.target.id==='resume-form')e.preventDefault()});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.step!==undefined)goStep(Number(b.dataset.step));if(b.hasAttribute('data-next'))goStep(state.step+1);if(b.hasAttribute('data-prev'))goStep(state.step-1);if(b.dataset.add){const kind=b.dataset.add;state.data[kind].push(kind==='experience'?{title:'',company:'',dates:'',details:''}:kind==='education'?{degree:'',school:'',dates:'',details:''}:{title:'',link:'',details:''});renderEditor();$(`#${kind}-${state.data[kind].length-1}-${kind==='education'?'degree':'title'}`)?.focus()}if(b.dataset.remove){const key=b.dataset.remove,index=Number(b.dataset.index);const removed=state.data[key].splice(index,1)[0];renderEditor();$('#toast').innerHTML=`Entry removed. <button id="undo-remove">Undo</button>`;$('#toast').classList.add('show');clearTimeout(toastTimer);$('#undo-remove').onclick=()=>{state.data[key].splice(index,0,removed);if(currentView==='editor')renderEditor();else save();notify('Entry restored.')};toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),8000)}if(b.dataset.move){const key=b.dataset.move,i=Number(b.dataset.index);if(i>0){[state.data[key][i-1],state.data[key][i]]=[state.data[key][i],state.data[key][i-1]];renderEditor()}}if(b.dataset.color){state.color=b.dataset.color;$$('.swatch').forEach(s=>{s.classList.toggle('selected',s.dataset.color===state.color);s.setAttribute('aria-pressed',s.dataset.color===state.color)});save();renderPreview()}if(b.dataset.mobile){const preview=b.dataset.mobile==='preview';$('#editor-view').classList.toggle('mobile-preview',preview);$$('[data-mobile]').forEach(s=>{const active=s===b;s.classList.toggle('active',active);s.setAttribute('aria-pressed',active)})}if(b.hasAttribute('data-clear'))$('#clear-dialog').showModal();if(b.hasAttribute('data-export')||b.hasAttribute('data-review'))requestExport()});
$('#confirm-clear').onclick=()=>{state.data=empty();state.step=0;$('#clear-dialog').close();renderEditor();notify('A fresh start. Your draft is cleared.')};
$('#print-button').onclick=()=>{if(!preparePrint())return;$('#export-dialog').close();let style=$('#paper-size-style');if(!style){style=document.createElement('style');style.id='paper-size-style';document.head.appendChild(style)}style.textContent=`@page { size: ${$('#paper-size').value==='Letter'?'Letter':'A4'}; margin: 15mm; }`;document.title=`${state.data.name} — Resume`;window.print();setTimeout(()=>{document.title='Folio — Your next chapter'},1000)};
$('#share-copy').onclick=copyResumeMessage;
$('#share-more').onclick=shareToMoreApps;
$('#share-pdf-file').onchange=updatePdfSharing;
$('#share-pdf-button').onclick=sharePdf;
$('#share-export').onclick=()=>{$('#share-dialog').close();requestExport()};
for(const id of ['share-whatsapp','share-email'])$('#'+id).addEventListener('click',async e=>{const link=e.currentTarget;if(link.dataset.needsPaste==='true'){e.preventDefault();const copied=await copyResumeMessage();if(copied){link.dataset.needsPaste='false';link.querySelector('small').textContent='Open app and paste';sharingStatus('Full resume copied. Choose '+(id==='share-email'?'Email':'WhatsApp')+' again to open the app, then paste your resume.')}}else sharingStatus('Opening your app. Choose a recipient and review the message before sending.')});
document.addEventListener('click',e=>{if(e.target.closest('[data-share]'))requestShare()});
window.addEventListener('beforeprint',preparePrint);
document.addEventListener('click',e=>{const a=e.target.closest('a[href="#templates"]');if(a){e.preventDefault();showView('templates')}});
const tips=[['01','Start with the role.','Read the job description before you write. Make your relevant experience easy to find, using the employer’s terminology where it truthfully describes your work.','Don’t add a skill just because it appears in the listing.'],['02','Show what changed.','A strong bullet connects an action to an outcome. Start with verbs like built, organized, researched, or improved. Include numbers when you have real evidence.','“Organized 6 workshops for 120 students” beats “Responsible for events.”'],['03','New here? You have a story.','Coursework, internships, volunteering, and personal projects show what you can do. Start with education and projects when they are your strongest evidence.','The First Chapter puts your education near the top.'],['04','Keep the structure simple.','Use recognizable headings, consistent dates, and readable text. Folio’s templates use a single column and real text, with no skill-rating charts or photos.','No template can guarantee an ATS pass or an interview.'],['05','Make every line earn its place.','Prioritize recent, relevant details. An early-career resume often fits on a page; an academic CV may need more. Useful content matters more than an arbitrary length.','Remove repeated points before making the text smaller.'],['06','Give it one final read.','Check your contact details, dates, spelling, links, and page breaks. Export your PDF and verify that the text can be selected. Follow the file format requested by the employer.','Use Share to send your resume through WhatsApp, email, or another app.']];
function renderTips(){$('#tips-view').innerHTML=`<div class="tips-intro"><div class="eyebrow">SMALL CHANGES. STRONGER STORY.</div><h1 id="tips-title">Good words.<br>Better first impressions.</h1><p>A few practical ways to make your experience shine.</p></div><div class="tips-grid">${tips.map(([n,title,body,note])=>`<article class="tip-card"><span class="tip-number">${n}</span><h2>${title}</h2><p>${body}</p><div class="tip-note">${note}</div></article>`).join('')}</div><div class="tips-cta"><div><h2>Ready for your next chapter?</h2><p>Your experience is the starting point.</p></div><button class="button dark" data-view="editor">Back to my resume</button></div><details class="research-notes"><summary>Behind Folio: what inspired the experience</summary><p>We reviewed the public product pages of 12 major resume builders in September 2026. Folio is an independent, simplified take on useful patterns, with original templates. Features and plan availability on those services can change.</p><div class="research-grid">${[['Canva','https://www.canva.com/create/resumes/','Browsable visual templates and personal style.'],['Novorésumé','https://novoresume.com/','Career-stage templates and contextual guidance.'],['Resume.io','https://resume.io/','A guided resume-building flow.'],['Zety','https://zety.com/resume-builder','Section-by-section writing support.'],['Enhancv','https://enhancv.com/','A focus on personal presentation.'],['Kickresume','https://www.kickresume.com/en/','Template customization and writing assistance.'],['Teal','https://www.tealhq.com/tools/resume-builder','Tailoring content to a target role.'],['Rezi','https://www.rezi.ai/rezi-docs/templates','Readable structure and simple formatting.'],['Resume Genius','https://resumegenius.com/','Role-specific examples and content guidance.'],['MyPerfectResume','https://www.myperfectresume.com/','Guided resume creation.'],['VisualCV','https://www.visualcv.com/resume-builder/','Resume examples and export options.'],['Resume.com','https://www.resume.com/','Straightforward resume creation and downloads.']].map(([name,url,lesson])=>`<div><a href="${url}" target="_blank" rel="noopener noreferrer">${name}</a><p>${lesson}</p></div>`).join('')}</div><p>Folio uses local writing prompts and a content checklist. It does not run AI analysis or certify ATS compatibility. Drafts stay in this browser; there is no account sync.</p></details>`}
function registerAgentTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const registrations=[{name:'get_resume_status',title:'Read resume status',description:'Read the selected template, visible editor section, and content checklist. Does not return personal resume content.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:(input)=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('This tool accepts an empty object.');return {template:state.template,section:steps[state.step],checks:checkData().map(([label,complete])=>({label,complete}))}}},{name:'set_resume_template',title:'Change resume template',description:'Apply an existing template and its default accent to the current resume and open the editor. Keeps all resume text.',inputSchema:{type:'object',properties:{template:{type:'string',enum:templates.map(t=>t.id)}},required:['template'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:(input)=>{if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='template'))throw new Error('Provide only a template ID.');const t=templates.find(t=>t.id===input.template);if(!t)throw new Error('Unknown resume template.');state.template=t.id;state.color=t.color;showView('editor');return {template:t.id,applied:true}}}];for(const tool of registrations){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch(e){}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
registerAgentTools();
if(['editor','tips'].includes(location.hash.slice(1)))showView(location.hash.slice(1));
